package io.github.jackotom.hongguo.android;
import java.io.*;import java.lang.reflect.*;import java.nio.file.Files;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.json.*;
/** Real pending-request ownership and bounded source retries, no network or device. */
public final class PlaybackSourcesLookupRetryTest {
 static int passed,failed,checks;static final String SID="880001",VID="880006";interface Checked{void run()throws Exception;}
 static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}static void rejects(Checked task,String message)throws Exception{try{task.run();}catch(Exception expected){checks++;return;}throw new AssertionError(message);}
 static void group(String name,Checked task){try{task.run();passed++;System.out.println("PASS "+name);}catch(Throwable e){failed++;System.out.println("FAIL "+name+": "+e.getClass().getSimpleName()+" "+e.getMessage());}finally{Thread.interrupted();}}
 static JSONArray arguments(String script)throws Exception{return new JSONArray("["+script.substring(script.lastIndexOf('(')+1,script.length()-1)+"]");}
 static JSONObject envelope(JSONArray a)throws Exception{return new JSONObject().put("requestId",a.getString(0)).put("seriesId",a.getString(1)).put("vid",a.getString(2)).put("requestedQuality",a.getString(3));}
 static JSONObject model(String name,String quality)throws Exception{JSONObject row=new JSONObject().put("url","https://cdn.qznovelvod.com/synthetic-lookup-"+name+".mp4").put("vid",VID).put("seriesId",SID).put("source","app").put("requestedQuality",quality);if(!quality.equals("auto")){int size=Integer.parseInt(quality.substring(0,quality.length()-1));row.put("width",size).put("height",size*2);}return row;}
 static void transientReply(JSONArray a,String code)throws Exception{PlaybackSources.result(envelope(a).put("error","App 片源网络请求失败，请稍后重试").put("errorCode",code));}
 static void requireBoundedRetry()throws Exception{try{PlaybackSources.class.getDeclaredMethod("resolveApp",String.class,String.class,String.class,boolean.class);}catch(NoSuchMethodException baseline){throw new AssertionError("initial source lookup lacks bounded retry owner");}}
 public static void main(String[]unused)throws Exception{MainActivity host=new MainActivity();PlaybackSources.attach(host);File dir=Files.createTempDirectory("lookup-contract-").toFile();try{
  group("initial DNS failure re-signs once with a new id and exact selected quality",()->{for(String quality:new String[]{"auto","720p","1080p"}){NetworkGuard.reset();List<JSONArray> calls=new ArrayList<>();host.callback=script->{try{JSONArray a=arguments(script);calls.add(a);if(calls.size()==1)transientReply(a,"ENOTFOUND");else{check(!calls.get(0).getString(0).equals(a.getString(0)),"retry owns a new opaque request id");PlaybackSources.result(envelope(calls.get(0)).put("playInfo",model("late-first","auto")));PlaybackSources.result(envelope(a).put("playInfo",model("new-second",quality)));}}catch(Exception e){throw new RuntimeException(e);}};long start=System.nanoTime();PlaybackSources.Plan p=PlaybackSources.resolve(SID,VID,quality);check(calls.size()==2&&p.requestedQuality.equals(quality)&&p.url.contains("new-second"),"initial DNS retry succeeds without stale callback or downgrade");check(System.nanoTime()-start>=2_000_000_000L,"DNS retry waits beyond Android 12 negative cache TTL");check(NetworkGuard.downloads==0,"lookup recovery never multiplies media transfers");}});
  group("two transient lookup failures stop after exactly two new requests",()->{NetworkGuard.reset();int[]calls={0};host.callback=script->{try{calls[0]++;transientReply(arguments(script),"ETIMEDOUT");}catch(Exception e){throw new RuntimeException(e);}};rejects(()->PlaybackSources.resolve(SID,VID,"1080p"),"two failed lookups returned media");check(calls[0]==2&&NetworkGuard.downloads==0,"initial source error gets at most one retry");});
  group("business malformed generic and unknown callback errors never auto retry",()->{for(String code:new String[]{"BUSINESS_REJECTED","INVALID_RESPONSE","QUALITY_UNAVAILABLE","ERR_NETWORK","UNKNOWN",""}){NetworkGuard.reset();int[]calls={0};host.callback=script->{try{calls[0]++;transientReply(arguments(script),code);}catch(Exception e){throw new RuntimeException(e);}};rejects(()->PlaybackSources.resolve(SID,VID,"720p"),"nontransient error produced model");check(calls[0]==1,"only whitelisted native transport codes can repeat lookup: "+code);}});
  group("caller reconnect and second media round do not nest lookup retries",()->{NetworkGuard.reset();int[]calls={0};host.callback=script->{try{calls[0]++;transientReply(arguments(script),"ENOTFOUND");}catch(Exception e){throw new RuntimeException(e);}};Method recover;try{recover=PlaybackSources.class.getDeclaredMethod("recover",String.class,String.class,String.class,boolean.class);}catch(NoSuchMethodException e){throw new AssertionError("missing caller-owned reconnect");}rejects(()->{try{recover.invoke(null,SID,VID,"1080p",false);}catch(InvocationTargetException e){throw(Exception)e.getCause();}},"caller reconnect returned media");check(calls[0]==1,"caller reconnect does not nest the initial lookup retry");JSONObject old=model("media-old","1080p");String url=old.getString("url");PlaybackSources.register(old,VID,false);NetworkGuard.outcomes.put(url,"http403");File part=new File(dir,"second-round.part");calls[0]=0;rejects(()->PlaybackSources.download(url,part,64,"1080p"),"failed refresh returned media");check(calls[0]==1&&NetworkGuard.downloads==2&&!part.exists(),"App 403 gets one same-URL retry, then model refresh stays one lookup");});
  group("initial retry backoff is interruptible and does not send its second request",()->{NetworkGuard.reset();int[]calls={0};host.callback=script->{try{calls[0]++;transientReply(arguments(script),"ENOTFOUND");}catch(Exception e){throw new RuntimeException(e);}};AtomicReference<Throwable> error=new AtomicReference<>();boolean[]flag={false};Thread worker=new Thread(()->{try{PlaybackSources.resolve(SID,VID,"1080p");}catch(Throwable e){error.set(e);flag[0]=Thread.currentThread().isInterrupted();}});worker.start();long end=System.nanoTime()+2_000_000_000L;while(worker.isAlive()&&worker.getState()!=Thread.State.TIMED_WAITING&&System.nanoTime()<end)Thread.sleep(2);check(worker.isAlive(),"initial lookup enters retry backoff");worker.interrupt();worker.join(1500);check(!worker.isAlive()&&error.get() instanceof InterruptedException&&flag[0]&&calls[0]==1,"interrupted initial retry preserves cancellation and makes no second callback");});
  group("hanging first callback expires and its late result cannot settle second request",()->{requireBoundedRetry();NetworkGuard.reset();List<JSONArray> calls=new ArrayList<>();int[]cancels={0};host.callback=script->{try{JSONArray a=arguments(script);if(a.length()<2){cancels[0]++;return;}calls.add(a);if(calls.size()==1)return;PlaybackSources.result(envelope(calls.get(0)).put("playInfo",model("stale-timed-out","auto")));PlaybackSources.result(envelope(a).put("playInfo",model("fresh-after-timeout","1080p")));}catch(Exception e){throw new RuntimeException(e);}};long start=System.nanoTime();PlaybackSources.Plan p=PlaybackSources.resolve(SID,VID,"1080p");long millis=(System.nanoTime()-start)/1_000_000L;check(calls.size()==2&&cancels[0]==1&&p.url.contains("fresh-after-timeout")&&p.requestedQuality.equals("1080p"),"timed-out first callback is cancelled and detached before a new id begins");check(millis>=14000&&millis<30000,"total lookup budget stays below 30s and per-attempt wait at most 28s");});
  System.out.println("SOURCE_LOOKUP_"+(failed==0?"OK":"FAILED")+" groupsPassed="+passed+" groupsFailed="+failed+" checks="+checks+" networkRequests=0 deviceTests=not_run");if(failed!=0)throw new AssertionError("lookup recovery gate failed");
 }finally{PlaybackSources.detach(host);Thread.interrupted();for(File file:dir.listFiles())file.delete();dir.delete();}}
}
